// Dedup: only pass through messages newer than the last one we processed.
// Uses n8n's workflow static data so this persists across executions.
const staticData = $getWorkflowStaticData('global');
const lastTs = parseFloat(staticData.lastProcessedTs || '0');

const messages = $input.all();
const candidates = [];

for (const msg of messages) {
  const text = (msg.json.text || '').trim();
  const ts = parseFloat(msg.json.ts || '0');

  // Skip anything we've already handled
  if (ts <= lastTs) continue;

  // Skip bot joins/leaves, channel_join, edits, and obviously non-job noise
  const subtype = msg.json.subtype || '';
  if (subtype) continue;
  if (text.length <= 80) continue;
  if (text.startsWith('<') && !text.includes('http')) continue;
  if (/has joined|has left/i.test(text)) continue;

  candidates.push({
    text,
    ts: msg.json.ts,
    slackUser: msg.json.user || 'unknown'
  });
}

// Update the high-water mark to the newest ts seen in this batch (processed or not),
// so a burst of noisy non-job messages doesn't get re-scanned forever.
const allTs = messages.map(m => parseFloat(m.json.ts || '0'));
if (allTs.length) {
  staticData.lastProcessedTs = String(Math.max(lastTs, ...allTs));
}

if (candidates.length === 0) {
  return [{ json: { hasJobs: false, jobs: [], jobCount: 0 } }];
}

return [{ json: { hasJobs: true, jobs: candidates, jobCount: candidates.length } }];

// Re-attach the original file's name + link (lost after the download/extract hop)
// by matching on binary file name, and pass along the extracted text.
const items = $input.all();
const driveFiles = $('Split Out: Resume Files').all();

const out = items.map((item, i) => {
  const driveFile = driveFiles[i]?.json || {};
  return {
    json: {
      fileName: driveFile.name || item.binary?.data?.fileName || 'unknown.pdf',
      webViewLink: driveFile.webViewLink || (driveFile.id ? `https://drive.google.com/file/d/${driveFile.id}/view` : ''),
      resumeText: (item.json.text || '').slice(0, 4000) // cap per-resume length so prompt stays manageable
    }
  };
});

return out;

// Take the first matching deck file from the raw Drive API response, if any.
const files = $input.first().json.files || [];
const deck = files[0] || {};
return [{
  json: {
    deckName: deck.name || '',
    deckLink: deck.webViewLink || (deck.id ? `https://drive.google.com/file/d/${deck.id}/view` : '')
  }
}];

function safeGet(nodeName, fallback = {}) {
  try {
    return $(nodeName).first().json;
  } catch (e) {
    return fallback;
  }
}// Pull the new job(s) that triggered this run.
const jobsData = $('IF: New Job(s) Found?').first().json;
const jobs = jobsData.jobs || [];

// Pull real, extracted resume profiles.
const profileAgg = $('Aggregate: All Candidate Profiles').first().json;
const fileNames = profileAgg.fileName || [];
const webViewLinks = profileAgg.webViewLink || [];
const resumeTexts = profileAgg.resumeText || [];

const profiles = fileNames.map((name, i) => ({
  fileName: name,
  link: webViewLinks[i] || '',
  resumeText: resumeTexts[i] || ''
}));

// Deck link (may be empty if no matching file found).
const deck = safeGet('Code: Pick Deck Link', { deckLink: '', name: '' });
// ── APPROVED CANDIDATES ROSTER (names/roles/emails Techdome allows us to propose) ──
const APPROVED = [
  { name: 'Rahul Joshi',         role: 'Full Stack / Backend Developer',   email: 'user@example.com' },
  { name: 'Aditya Pratap Singh', role: 'Full Stack Developer',             email: '' },
  { name: 'Pratiksha Prasad',    role: 'Frontend / React Developer',       email: '' },
  { name: 'Ashutosh Pandey',     role: 'Backend Developer',                email: '' },
  { name: 'Het Patel',           role: 'Full Stack Developer',             email: '' },
  { name: 'Gaurav Chouhan',      role: 'Developer',                       email: '' },
  { name: 'Raman R.',            role: 'Developer',                       email: '' },
  { name: 'Anmol Kushwah',       role: 'Developer',                       email: 'user@example.com' },
  { name: 'Aditya Jain',         role: 'Project Manager / Delivery Head',  email: 'user@example.com' }
];

// Match each approved candidate to their extracted resume text by filename.
function findProfileFor(candidateName) {
  const parts = candidateName.toLowerCase().split(' ').filter(p => p.length > 3);
  return profiles.find(p => {
    const fname = p.fileName.toLowerCase();
    return parts.some(part => fname.includes(part));
  });
}

const candidateBlock = APPROVED.map(c => {
  const p = findProfileFor(c.name);
  const resumeSnippet = p?.resumeText ? p.resumeText.slice(0, 1500) : '(no resume on file — do not select unless no other option)';
  const link = p?.link ? `Resume link: ${p.link}` : '(no resume link on file)';
  return `### ${c.name} — ${c.role}\n${link}\nEmail: ${c.email || 'unknown'}\nResume excerpt:\n${resumeSnippet}`;
}).join('\n\n');

const jobsBlock = jobs.map((j, i) => `=== JOB ${i + 1} ===\n${j.text}`).join('\n\n');

const systemPrompt = `You are Techdome's Upwork proposal writer. Techdome is a 40-person software agency based in Indore, India.

━━ APPROVED CANDIDATES (NEVER propose anyone not on this list; base your pick on their actual resume excerpt below, not the job order) ━━
${candidateBlock}

━━ PROPOSAL WRITING RULES ━━
- Hard limit: 1,800 characters total (~200-300 words)
- No em dashes (—). Use commas, colons, or rephrase.
- Never open with "Hi, I'm..." or "I am a developer with X years..."
- Mirror 1-2 phrases from the client's own job post back to them
- Structure: Hook (specific business outcome, referencing their post) -> 2-sentence proof block (one real project + outcome, one tech credential, drawn from the resume excerpt, never fabricated) -> 1-sentence approach -> up to 2 specific clarifying questions -> brief no-pressure CTA
- Max 2 client-facing questions, specific and answerable
- Signature format: [Candidate First Name] | Techdome | [email if known, else omit]
- Budget >= $15/hr or >= $3,000/month: add one qualifying question about timeline or team size
- Budget < $10/hr: skip the proposal entirely and set skip_reason
- Select the BEST-MATCHING candidate strictly from the approved list, based on genuine overlap between their resume excerpt and the job's required skills
- If a company deck link is provided below, mention in proposal_notes (not in the proposal body itself) that the deck is available to attach

Company deck: ${deck.deckLink ? deck.deckLink : '(none found)'}

━━ OUTPUT FORMAT ━━
Return a valid JSON array, one object per job:
[
  {
    "job_index": 0,
    "selected_candidate": "Full name from approved list",
    "candidate_email": "email or empty string",
    "resume_link": "Google Drive URL or empty string",
    "proposal_text": "Full proposal text (max 1800 chars)",
    "match_reason": "One sentence on why this candidate's actual resume fits this job",
    "skipped": false,
    "skip_reason": ""
  }
]
If a job is skipped, set skipped: true, skip_reason to the reason, and proposal_text to empty string.
Return ONLY the JSON array, no markdown, no extra text.`;

const userMessage = `Process the following new Upwork job(s) posted in #your-upwork-jobs-channel and return a proposal for each:\n\n${jobsBlock}`;

return [{
  json: {
    systemPrompt,
    userMessage,
    jobs,
    deckLink: deck.deckLink || '',
    jobCount: jobs.length
  }
}];

