// Parse Gemini's JSON response and build email/Slack/ClickUp payloads.
const raw = $input.first().json;
const deckLink = $('Code: Build AI Prompt').first().json.deckLink || '';
let proposals = [];

try {
  let content = raw.candidates?.[0]?.content?.parts?.[0]?.text || '';
  content = content.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  proposals = JSON.parse(content);
} catch (e) {
  const text = raw.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const match = text.match(/\[\s*\{[\s\S]*\}\s*\]/m);
  if (match) {
    try { proposals = JSON.parse(match[0]); } catch (_) {}
  }
}

if (!Array.isArray(proposals) || proposals.length === 0) {
  return [{ json: {
    hasProposals: false,
    proposals: [],
    emailSubject: 'Upwork: No proposals generated',
    emailBody: 'Gemini could not generate proposals for this batch. Please review the job(s) manually in #your-upwork-jobs-channel.',
    slackMessage: ':warning: Gemini could not generate proposals for this batch. Check #your-upwork-jobs-channel manually.',
    clickupTitle: 'Upwork - Review required (AI parse error)'
  }}];
}

const activeProposals = proposals.filter(p => !p.skipped);
const skippedProposals = proposals.filter(p => p.skipped);

let emailBody = "Hi team,\n\nHere are today's Upwork proposal(s). Please review and submit within 1 hour.\n\n";

for (const p of activeProposals) {
  emailBody += `===========================================\n`;
  emailBody += `CANDIDATE: ${p.selected_candidate}\n`;
  if (p.resume_link) emailBody += `RESUME: ${p.resume_link}\n`;
  if (deckLink) emailBody += `COMPANY DECK: ${deckLink}\n`;
  if (p.match_reason) emailBody += `WHY THIS CANDIDATE: ${p.match_reason}\n`;
  emailBody += `\nPROPOSAL TEXT (copy-paste to Upwork):\n`;
  emailBody += `-------------------------------------------\n`;
  emailBody += `${p.proposal_text}\n`;
  emailBody += `===========================================\n\n`;
}

if (skippedProposals.length > 0) {
  emailBody += `\nSKIPPED JOBS (budget too low or disqualified):\n`;
  for (const p of skippedProposals) {
    emailBody += `- Job ${p.job_index + 1}: ${p.skip_reason}\n`;
  }
}

emailBody += `\nPlease submit within 1 hour.\nTechdome Automation`;

const jobCount = activeProposals.length;
const today = new Date().toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short' });
const clickupTitle = `Upwork - ${jobCount} proposal${jobCount !== 1 ? 's' : ''} to submit (${today})`;

const slackLines = activeProposals.map(p =>
  `:pencil: *${p.selected_candidate}* -> proposal ready${p.resume_link ? ' | <' + p.resume_link + '|Resume>' : ''}`
);
const slackMessage = `:briefcase: *New Upwork proposal${jobCount !== 1 ? 's' : ''} generated (${jobCount} job${jobCount !== 1 ? 's' : ''})*\n${slackLines.join('\n')}${deckLink ? '\nDeck: ' + deckLink : ''}\nEmail sent to team. Submit within 1 hour.`;

// Due date = today at 10 PM IST (16:30 UTC), in ms.
const now = new Date();
const due = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 16, 30, 0, 0));
if (due <= now) due.setUTCDate(due.getUTCDate() + 1);

return [{ json: {
  hasProposals: activeProposals.length > 0,
  proposals: activeProposals,
  emailSubject: `Upwork Proposals - ${jobCount} Job${jobCount !== 1 ? 's' : ''} - Submit by 10 PM IST`,
  emailBody,
  slackMessage,
  clickupTitle,
  deckLink,
  dueDate: due.getTime()
}}];

// One item per proposal, so the ClickUp node creates one task per proposal.
const data = $('Code: Parse AI Response').first().json;
return (data.proposals || []).map(p => ({ json: { ...p, deckLink: data.deckLink, dueDate: data.dueDate } }));
